    [HttpPost] [ValidateAntiForgeryToken]
    public ActionResult Edit([Bind("DepartmentID", "Name", "Budget", "StartDate", "InstructorID", "RowVersion")] Department department)
    {
        try
        {
            if (ModelState.IsValid)
            {
                db.Entry(department).State = EntityState.Modified;
                db.SaveChanges();
                SendEntityNotification("Department", department.DepartmentID.ToString(), department.Name, EntityOperation.UPDATE);
                return RedirectToAction("Index");
            }
        }
        catch (DbUpdateConcurrencyException ex)
        {
            var entry = ex.Entries.Single();
            var clientValues = (Department)entry.Entity;
            var databaseEntry = entry.GetDatabaseValues();
            if (databaseEntry == null)
            {
                ModelState.AddModelError(string.Empty, "Unable to save changes. The department was deleted by another user.");
            }
            else
            {
                var databaseValues = (Department)databaseEntry.ToObject();
                // ... adds model errors for each changed field
                ModelState.AddModelError(string.Empty, "The record you attempted to edit was modified by another user...");
                department.RowVersion = databaseValues.RowVersion;
            }
        }
        ViewBag.InstructorID = new SelectList(db.Instructors, "ID", "FullName", department.InstructorID);
        return View(department);
    }

    public ActionResult Delete(int? id)
    {
        if (id == null) return new StatusCodeResult((int)HttpStatusCode.BadRequest);
        Department department = db.Departments.Find(id);
        if (department == null) return NotFound();
        return View(department);
    }

