using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        private static IQueryable<int> CreateSource(int count)
        {
            return Enumerable.Range(1, count).AsQueryable();
        }

        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.Equal(3, result.Count);
            Assert.Equal(new[] { 1, 2, 3 }, result.ToArray());
        }

        [Fact]
        public void Create_MiddlePage_ReturnsCorrectItems()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

            Assert.Equal(3, result.Count);
            Assert.Equal(new[] { 4, 5, 6 }, result.ToArray());
        }

        [Fact]
        public void Create_LastPage_ReturnsCorrectItems()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 4, pageSize: 3);

            Assert.Single(result);
            Assert.Equal(10, result[0]);
        }

        [Fact]
        public void Create_SetsPageIndex()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_SetsTotalPages()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.Equal(4, result.TotalPages);
        }

        [Fact]
        public void Create_SinglePage_SetsTotalPagesToOne()
        {
            var source = CreateSource(3);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 5);

            Assert.Equal(1, result.TotalPages);
            Assert.Equal(3, result.Count);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 4, pageSize: 3);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var source = CreateSource(10);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_ExactMultiple_CorrectTotalPages()
        {
            var source = CreateSource(9);

            var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

            Assert.Equal(3, result.TotalPages);
            Assert.Equal(3, result.Count);
        }

        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<int> { 10, 20, 30 };

            var result = new PaginatedList<int>(items, count: 10, pageIndex: 1, pageSize: 5);

            Assert.Equal(3, result.Count);
            Assert.Contains(10, result);
            Assert.Contains(20, result);
            Assert.Contains(30, result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(2, result.TotalPages);
        }
    }
}

