using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    [Collection("NotificationServiceTests")]
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            // Drain the static queue before each test to prevent cross-test interference
            var drainer = new NotificationService();
            while (drainer.ReceiveNotification() != null) { }
            _sut = new NotificationService();
        }

        public void Dispose()
        {
            // Drain the static queue after each test as well
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        // ── Message generation with display name ──

        [Fact]
        public void SendNotification_WithDisplayName_CREATE_GeneratesCorrectMessage()
        {
            _sut.SendNotification("Student", "42", "Alice Smith", EntityOperation.CREATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("New", result.Message);
            Assert.Contains("has been created", result.Message);
            Assert.Contains("Alice Smith", result.Message);
            // Verify it uses the display name format, not the ID format
            Assert.DoesNotContain("ID:", result.Message);
            Assert.Equal("New Student 'Alice Smith' has been created", result.Message);
        }

        [Fact]
        public void SendNotification_WithDisplayName_UPDATE_GeneratesCorrectMessage()
        {
            _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("has been updated", result.Message);
            Assert.Contains("Chemistry", result.Message);
            Assert.DoesNotContain("New", result.Message);
            Assert.Equal("Course 'Chemistry' has been updated", result.Message);
        }

        [Fact]
        public void SendNotification_WithDisplayName_DELETE_GeneratesCorrectMessage()
        {
            _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("has been deleted", result.Message);
            Assert.Contains("Engineering", result.Message);
            Assert.DoesNotContain("New", result.Message);
            Assert.Equal("Department 'Engineering' has been deleted", result.Message);
        }

        // ── Message generation without display name ──

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
        {
            _sut.SendNotification("Student", "99", null, EntityOperation.CREATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("ID:", result.Message);
            Assert.Contains("99", result.Message);
            Assert.DoesNotContain("'", result.Message); // No quotes means no display name format
            Assert.Equal("New Student (ID: 99) has been created", result.Message);
        }

        // ── Property assertions ──

        [Fact]
        public void SendNotification_SetsEntityType()
        {
            _sut.SendNotification("Instructor", "7", "Dr. Jones", EntityOperation.UPDATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("Instructor", result.EntityType);
            // Also verify it's distinct from EntityId
            Assert.NotEqual(result.EntityType, result.EntityId);
        }

        [Fact]
        public void SendNotification_SetsEntityId()
        {
            _sut.SendNotification("Course", "CS-201", "Data Structures", EntityOperation.CREATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("CS-201", result.EntityId);
            Assert.NotEqual(result.EntityId, result.EntityType);
        }

        [Fact]
        public void SendNotification_SetsOperation()
        {
            _sut.SendNotification("Student", "1", "Bob", EntityOperation.DELETE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("DELETE", result.Operation);
            // Verify it matches the enum's ToString()
            Assert.Equal(EntityOperation.DELETE.ToString(), result.Operation);
        }

        [Fact]
        public void SendNotification_SetsCreatedBy_WhenProvided()
        {
            _sut.SendNotification("Student", "1", "Bob", EntityOperation.CREATE, "john.doe");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("john.doe", result.CreatedBy);
            Assert.NotEqual("System", result.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedByToSystem_WhenNull()
        {
            _sut.SendNotification("Student", "1", "Bob", EntityOperation.CREATE, null);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("System", result.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsIsReadFalse()
        {
            _sut.SendNotification("Student", "1", "Bob", EntityOperation.CREATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.False(result.IsRead);
        }

        // ── Overload delegation ──

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_DelegatesToFullOverload()
        {
            // The 3-param overload passes null for entityDisplayName
            _sut.SendNotification("Course", "55", EntityOperation.UPDATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            // Should use the ID format since no display name was provided
            Assert.Contains("ID: 55", result.Message);
            Assert.Equal("Course", result.EntityType);
            Assert.Equal("55", result.EntityId);
            Assert.Equal("UPDATE", result.Operation);
            Assert.Equal("admin", result.CreatedBy);
        }

        // ── Receive ──

        [Fact]
        public void ReceiveNotification_ReturnsNull_WhenQueueEmpty()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_ReturnsNotification_WhenQueueHasItems()
        {
            _sut.SendNotification("Student", "10", "Jane", EntityOperation.CREATE, "admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("Student", result.EntityType);
            Assert.Equal("10", result.EntityId);
        }

        [Fact]
        public void ReceiveNotification_DequeuesToCorrectOrder_FIFO()
        {
            _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE, "admin");
            _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE, "admin");
            _sut.SendNotification("Department", "3", "Third", EntityOperation.DELETE, "admin");

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();
            var fourth = _sut.ReceiveNotification();

            Assert.NotNull(first);
            Assert.NotNull(second);
            Assert.NotNull(third);
            Assert.Null(fourth);

            Assert.Equal("1", first.EntityId);
            Assert.Equal("2", second.EntityId);
            Assert.Equal("3", third.EntityId);

            // Verify distinct operations in order
            Assert.Equal("CREATE", first.Operation);
            Assert.Equal("UPDATE", second.Operation);
            Assert.Equal("DELETE", third.Operation);
        }

        // ── No-op methods ──

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(42));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        // ── Queue cap ──

        [Fact]
        public void QueueCap_EnforcesMaxLength()
        {
            // Enqueue 510 items (exceeds the 500 cap)
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Item", i.ToString(), $"Item{i}", EntityOperation.CREATE, "admin");
            }

            // Drain the queue and count how many items remain
            int count = 0;
            while (_sut.ReceiveNotification() != null)
            {
                count++;
            }

            // Queue should not exceed 500 items
            Assert.True(count <= 500, $"Queue had {count} items, expected <= 500");
            // But it should have a substantial number of items (at least 490 to account for concurrency)
            Assert.True(count >= 490, $"Queue had {count} items, expected >= 490");
        }
    }
}

