using System;
using System.Text.Json;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = CreateContext(Guid.NewGuid().ToString());
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            DrainNotificationQueue();
            _controller?.Dispose();
            _context?.Dispose();
        }

        private static SchoolContext CreateContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Arrange
            DrainNotificationQueue();

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            Assert.True(root.GetProperty("success").GetBoolean());
            Assert.Equal(0, root.GetProperty("count").GetInt32());
            Assert.Equal(JsonValueKind.Array, root.GetProperty("notifications").ValueKind);
            Assert.Equal(0, root.GetProperty("notifications").GetArrayLength());
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            // Arrange
            DrainNotificationQueue();

            var svc = new NotificationService();
            svc.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");
            svc.SendNotification("Course", "2", EntityOperation.UPDATE, "TestUser");
            svc.SendNotification("Instructor", "3", EntityOperation.DELETE, "TestUser");

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            Assert.True(root.GetProperty("success").GetBoolean());
            Assert.Equal(3, root.GetProperty("count").GetInt32());

            var notifications = root.GetProperty("notifications");
            Assert.Equal(3, notifications.GetArrayLength());

            // Verify the first notification has expected structure and content
            var first = notifications[0];
            Assert.Equal("Student", first.GetProperty("entityType").GetString());
            Assert.Equal("1", first.GetProperty("entityId").GetString());
            Assert.Equal("CREATE", first.GetProperty("operation").GetString());
            Assert.False(first.GetProperty("isRead").GetBoolean());
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Arrange
            DrainNotificationQueue();

            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), EntityOperation.CREATE, "TestUser");
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            Assert.True(root.GetProperty("success").GetBoolean());
            Assert.Equal(10, root.GetProperty("count").GetInt32());
            Assert.Equal(10, root.GetProperty("notifications").GetArrayLength());
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Arrange
            DrainNotificationQueue();

            // Act
            var result = _controller.MarkAsRead(42);

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            using var doc = JsonDocument.Parse(json);
            Assert.True(doc.RootElement.GetProperty("success").GetBoolean());
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Arrange
            DrainNotificationQueue();

            // Act
            var result = _controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Null(viewResult.ViewName);
        }
    }
}

