using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests
    {
        private static SchoolContext CreateContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private static Department CreateDepartment(string name = "Engineering", decimal budget = 100000m, int? instructorId = null)
        {
            return new Department
            {
                Name = name,
                Budget = budget,
                StartDate = new DateTime(2023, 9, 1),
                InstructorID = instructorId
            };
        }

        private static Instructor CreateInstructor(string lastName = "Smith", string firstName = "John")
        {
            return new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName,
                HireDate = new DateTime(2010, 1, 15)
            };
        }

        // ===== Index Tests =====

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Index_ReturnsViewWithDepartments));
            context.Departments.Add(CreateDepartment("Engineering", 100000m));
            context.Departments.Add(CreateDepartment("Mathematics", 75000m));
            context.SaveChanges();

            using var controller = new DepartmentsController(context);
            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Department>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Contains(model, d => d.Name == "Engineering");
            Assert.Contains(model, d => d.Name == "Mathematics");
        }

        // ===== Details Tests =====

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Details_NullId_ReturnsBadRequest));
            using var controller = new DepartmentsController(context);

            var result = controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Details_NotFound_ReturnsNotFound));
            using var controller = new DepartmentsController(context);

            var result = controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsDepartment()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Details_ValidId_ReturnsDepartment));
            var dept = CreateDepartment("Physics", 50000m);
            context.Departments.Add(dept);
            context.SaveChanges();

            using var controller = new DepartmentsController(context);
            var result = controller.Details(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal("Physics", model.Name);
            Assert.Equal(50000m, model.Budget);
        }

        // ===== Create GET Tests =====

        [Fact]
        public void Create_GET_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_ReturnsView));
            using var controller = new DepartmentsController(context);

            var result = controller.Create();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void Create_GET_SetsViewBagInstructorID()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_SetsViewBagInstructorID));
            var instructor = CreateInstructor("Doe", "Jane");
            context.Instructors.Add(instructor);
            context.SaveChanges();

            using var controller = new DepartmentsController(context);
            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var selectList = Assert.IsType<SelectList>(result.ViewData["InstructorID"]);
            Assert.Single(selectList);
        }

        // ===== Create POST Tests =====

        [Fact]
        public void Create_POST_ValidDepartment_RedirectsToIndex()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_ValidDepartment_RedirectsToIndex));
            using var controller = new DepartmentsController(context);
            var dept = CreateDepartment("Chemistry", 60000m);

            var result = controller.Create(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidDepartment_SavesToDB()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_ValidDepartment_SavesToDB));
            using var controller = new DepartmentsController(context);
            var dept = CreateDepartment("Biology", 45000m);

            controller.Create(dept);

            Assert.Equal(1, context.Departments.Count());
            var saved = context.Departments.First();
            Assert.Equal("Biology", saved.Name);
            Assert.Equal(45000m, saved.Budget);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_InvalidModelState_ReturnsView));
            using var controller = new DepartmentsController(context);
            controller.ModelState.AddModelError("Name", "Required");
            var dept = CreateDepartment("Bad");

            var result = controller.Create(dept) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal("Bad", model.Name);
            Assert.Equal(0, context.Departments.Count());
        }

        [Fact]
        public void Create_POST_SendsCreateNotification()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_SendsCreateNotification));
            using var controller = new DepartmentsController(context);
            var dept = CreateDepartment("Art History", 30000m);

            controller.Create(dept);

            var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("created", notification.Message, StringComparison.OrdinalIgnoreCase);
            Assert.Contains("Art History", notification.Message);
            Assert.Equal("Department", notification.EntityType);
        }

        // ===== Edit GET Tests =====

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Edit_GET_NullId_ReturnsBadRequest));
            using var controller = new DepartmentsController(context);

            var result = controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_NotFound_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Edit_GET_NotFound_ReturnsNotFound));
            using var controller = new DepartmentsController(context);

            var result = controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsDepartment()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Edit_GET_ValidId_ReturnsDepartment));
            var dept = CreateDepartment("History", 55000m);
            context.Departments.Add(dept);
            context.SaveChanges();

            using var controller = new DepartmentsController(context);
            var result = controller.Edit(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal("History", model.Name);
            Assert.Equal(55000m, model.Budget);
        }

        [Fact]
        public void Edit_GET_SetsViewBagInstructorID()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Edit_GET_SetsViewBagInstructorID));
            var instructor = CreateInstructor("Adams", "Alice");
            context.Instructors.Add(instructor);
            context.SaveChanges();
