using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests
    {
        private static SchoolContext CreateContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private static CoursesController CreateController(SchoolContext context)
        {
            var mockEnv = new Mock<IWebHostEnvironment>();
            mockEnv.Setup(e => e.ContentRootPath).Returns("/fake/path");
            mockEnv.Setup(e => e.WebRootPath).Returns("/fake/wwwroot");
            var mockLogger = new Mock<ILogger<CoursesController>>();
            return new CoursesController(context, mockEnv.Object, mockLogger.Object);
        }

        private static Department CreateTestDepartment(int id = 1, string name = "Engineering")
        {
            return new Department
            {
                DepartmentID = id,
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
        }

        private static Course CreateTestCourse(int courseId, string title, int departmentId, int credits = 3)
        {
            return new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = credits,
                DepartmentID = departmentId
            };
        }

        // ==================== Index ====================

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Index_ReturnsViewWithCourses));
            var dept1 = CreateTestDepartment(1, "Math");
            var dept2 = CreateTestDepartment(2, "Science");
            context.Departments.AddRange(dept1, dept2);
            context.Courses.Add(CreateTestCourse(1001, "Calculus", 1));
            context.Courses.Add(CreateTestCourse(2002, "Physics", 2));
            context.SaveChanges();

            using var controller = CreateController(context);
            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Contains(model, c => c.Title == "Calculus" && c.CourseID == 1001);
            Assert.Contains(model, c => c.Title == "Physics" && c.CourseID == 2002);
            // Verify departments are loaded via Include
            Assert.All(model, c => Assert.NotNull(c.Department));
        }

        // ==================== Details ====================

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Details_NullId_ReturnsBadRequest));
            using var controller = CreateController(context);

            var result = controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourse()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Details_ValidId_ReturnsCourse));
            var dept = CreateTestDepartment(1, "History");
            context.Departments.Add(dept);
            context.Courses.Add(CreateTestCourse(3003, "World History", 1, 4));
            context.SaveChanges();

            using var controller = CreateController(context);
            var result = controller.Details(3003) as ViewResult;

            Assert.NotNull(result);
            var course = Assert.IsType<Course>(result.Model);
            Assert.Equal(3003, course.CourseID);
            Assert.Equal("World History", course.Title);
            Assert.Equal(4, course.Credits);
            Assert.NotNull(course.Department);
            Assert.Equal("History", course.Department.Name);
        }

        // ==================== Create GET ====================

        [Fact]
        public void Create_GET_ReturnsViewWithNewCourse()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_ReturnsViewWithNewCourse));
            using var controller = CreateController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(0, model.CourseID);
            Assert.Null(model.Title);
        }

        [Fact]
        public void Create_GET_SetsViewBagDepartmentID()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_SetsViewBagDepartmentID));
            var dept1 = CreateTestDepartment(1, "Art");
            var dept2 = CreateTestDepartment(2, "Music");
            context.Departments.AddRange(dept1, dept2);
            context.SaveChanges();

            using var controller = CreateController(context);
            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var selectList = Assert.IsAssignableFrom<SelectList>(controller.ViewBag.DepartmentID);
            Assert.Equal(2, selectList.Count());
        }

        // ==================== Create POST ====================

        [Fact]
        public void Create_POST_ValidCourse_NoFile_RedirectsToIndex()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_ValidCourse_NoFile_RedirectsToIndex));
            var dept = CreateTestDepartment(1, "Biology");
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = CreateTestCourse(4004, "Cell Biology", 1);
            using var controller = CreateController(context);
            var result = controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_POST_ValidCourse_SavesToDB()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_ValidCourse_SavesToDB));
            var dept = CreateTestDepartment(1, "Chemistry");
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = CreateTestCourse(5005, "Organic Chemistry", 1, 4);
            using var controller = CreateController(context);
            controller.Create(course, null);

            var saved = context.Courses.Find(5005);
            Assert.NotNull(saved);
            Assert.Equal("Organic Chemistry", saved.Title);
            Assert.Equal(4, saved.Credits);
            Assert.Equal(1, saved.DepartmentID);
        }

        [Fact]
        public void Create_POST_InvalidExtension_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_InvalidExtension_AddsModelError));
            var dept = CreateTestDepartment(1, "English");
            context.Departments.Add(dept);
            context.SaveChanges();

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("document.txt");
            mockFile.Setup(f => f.Length).Returns(100);

            var course = CreateTestCourse(6006, "Literature", 1);
            using var controller = CreateController(context);
            var result = controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errorMessages = controller.ModelState["teachingMaterialImage"]!.Errors.Select(e => e.ErrorMessage).ToList();
            Assert.Contains(errorMessages, m => m.Contains("valid image file"));
            // Verify course was NOT saved
            Assert.Null(context.Courses.Find(6006));
        }

        [Fact]
        public void Create_POST_OversizedFile_AddsModelError()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_OversizedFile_AddsModelError));
            var dept = CreateTestDepartment(1, "Philosophy");
            context.Departments.Add(dept);
