            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("large.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

            var course = CreateTestCourse(7007, "Ethics", 1);
            using var controller = CreateController(context);
            var result = controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errorMessages = controller.ModelState["teachingMaterialImage"]!.Errors.Select(e => e.ErrorMessage).ToList();
            Assert.Contains(errorMessages, m => m.Contains("5MB"));
            // Verify course was NOT saved
            Assert.Null(context.Courses.Find(7007));
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_InvalidModelState_ReturnsView));
            var dept = CreateTestDepartment(1, "Sociology");
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = CreateTestCourse(8008, "Intro Sociology", 1);
            using var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Title is required");

            var result = controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
            var returnedCourse = Assert.IsType<Course>(result.Model);
            Assert.Equal(8008, returnedCourse.CourseID);
            Assert.Equal("Intro Sociology", returnedCourse.Title);
