using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        private static SchoolContext CreateContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private static StudentsController CreateController(SchoolContext context)
        {
            var controller = new StudentsController(context);
            // Set up TempData so TempData["..."] = ... doesn't throw
            controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), 
                new SessionStateTempDataProvider(new SessionStore()));
            return controller;
        }

        private static Student MakeStudent(string lastName, string firstName, DateTime enrollmentDate)
        {
            return new Student
            {
                LastName = lastName,
                FirstMidName = firstName,
                EnrollmentDate = enrollmentDate
            };
        }

        // ===================== INDEX TESTS =====================

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAscending()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_DefaultSort_OrdersByLastNameAscending)}");
            context.Students.Add(MakeStudent("Zeta", "Alice", new DateTime(2023, 1, 1)));
            context.Students.Add(MakeStudent("Alpha", "Bob", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Alpha", model[0].LastName);
            Assert.Equal("Zeta", model[1].LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDescending()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_NameDescSort_OrdersByLastNameDescending)}");
            context.Students.Add(MakeStudent("Alpha", "Alice", new DateTime(2023, 1, 1)));
            context.Students.Add(MakeStudent("Zeta", "Bob", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index("name_desc", null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Zeta", model[0].LastName);
            Assert.Equal("Alpha", model[1].LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAscending()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_DateSort_OrdersByEnrollmentDateAscending)}");
            context.Students.Add(MakeStudent("Late", "Alice", new DateTime(2025, 6, 1)));
            context.Students.Add(MakeStudent("Early", "Bob", new DateTime(2020, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index("Date", null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Early", model[0].LastName);
            Assert.Equal("Late", model[1].LastName);
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_DateDescSort_OrdersByEnrollmentDateDescending)}");
            context.Students.Add(MakeStudent("Early", "Bob", new DateTime(2020, 1, 1)));
            context.Students.Add(MakeStudent("Late", "Alice", new DateTime(2025, 6, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index("date_desc", null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.Equal("Late", model[0].LastName);
            Assert.Equal("Early", model[1].LastName);
        }

        [Fact]
