        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_SearchString_FiltersStudentsByLastName)}");
            context.Students.Add(MakeStudent("Smith", "John", new DateTime(2023, 1, 1)));
            context.Students.Add(MakeStudent("Jones", "Jane", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(null, null, "Smith", null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
            Assert.Equal("John", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_SearchByFirstName_FiltersStudents)}");
