            context.Students.Add(MakeStudent("Doe", "Bob", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(null, null, "Alice", null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Alice", model[0].FirstMidName);
            Assert.Equal("Doe", model[0].LastName);
        }

        [Fact]
        public void Index_Pagination_ReturnsCorrectPage()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_Pagination_ReturnsCorrectPage)}");
            for (int i = 1; i <= 15; i++)
            {
                context.Students.Add(MakeStudent($"Student{i:D2}", $"First{i}", new DateTime(2023, 1, i)));
            }
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Index(null, null, null, 2) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(5, model.Count);
            Assert.Equal(2, model.PageIndex);
            Assert.Equal(2, model.TotalPages);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_NewSearchString_ResetsPageTo1)}");
            context.Students.Add(MakeStudent("TestName", "First", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            // When searchString is not null, page should be reset to 1
            var result = controller.Index(null, null, "TestName", 5) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
            Assert.Single(model);
        }

        [Fact]
        public void Index_NullSearchString_UsesCurrentFilter()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_NullSearchString_UsesCurrentFilter)}");
            context.Students.Add(MakeStudent("Smith", "John", new DateTime(2023, 1, 1)));
            context.Students.Add(MakeStudent("Jones", "Jane", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);
            // searchString is null, so currentFilter ("Smith") should be used
            var result = controller.Index(null, "Smith", null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
            Assert.Equal("Smith", controller.ViewBag.CurrentFilter);
        }

        [Fact]
        public void Index_SetsViewBagProperties()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Index_SetsViewBagProperties)}");
            context.Students.Add(MakeStudent("Test", "Student", new DateTime(2023, 1, 1)));
            context.SaveChanges();

            var controller = CreateController(context);

            // Default sort order (null)
            controller.Index(null, null, "myfilter", null);
            Assert.Null(controller.ViewBag.CurrentSort);
            Assert.Equal("name_desc", controller.ViewBag.NameSortParm);
            Assert.Equal("Date", controller.ViewBag.DateSortParm);
            Assert.Equal("myfilter", controller.ViewBag.CurrentFilter);

            // With "Date" sort order → DateSortParm flips to "date_desc"
            using var context2 = CreateContext($"StudentsCtrl_{nameof(Index_SetsViewBagProperties)}_2");
            context2.Students.Add(MakeStudent("Test", "Student", new DateTime(2023, 1, 1)));
            context2.SaveChanges();
            var controller2 = CreateController(context2);
            controller2.Index("Date", null, null, null);
            Assert.Equal("Date", controller2.ViewBag.CurrentSort);
            Assert.Equal("", controller2.ViewBag.NameSortParm);
            Assert.Equal("date_desc", controller2.ViewBag.DateSortParm);
        }

