            var student = MakeStudent("DetailLast", "DetailFirst", new DateTime(2023, 5, 15));
            context.Students.Add(student);
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("DetailLast", model.LastName);
            Assert.Equal("DetailFirst", model.FirstMidName);
            Assert.Equal(new DateTime(2023, 5, 15), model.EnrollmentDate);
            Assert.Equal(student.ID, model.ID);
        }

        [Fact]
        public void Details_IncludesEnrollments()
        {
            DrainNotificationQueue();
            using var context = CreateContext($"StudentsCtrl_{nameof(Details_IncludesEnrollments)}");
            var course = new Course { CourseID = 1001, Title = "Chemistry", Credits = 3 };
            context.Courses.Add(course);
            var student = MakeStudent("Enrolled", "Student", new DateTime(2023, 1, 1));
            context.Students.Add(student);
            context.SaveChanges();

            var enrollment = new Enrollment { CourseID = 1001, StudentID = student.ID, Grade = Grade.A };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var controller = CreateController(context);
            var result = controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
            var loadedEnrollment = model.Enrollments.First();
            Assert.Equal(1001, loadedEnrollment.CourseID);
            Assert.NotNull(loadedEnrollment.Course);
            Assert.Equal("Chemistry", loadedEnrollment.Course.Title);
            Assert.Equal(Grade.A, loadedEnrollment.Grade);
        }

