            {
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2023, 9, 1),
                InstructorID = instructorId
            };
        }

        /// <summary>
        /// Seeds an instructor with a course assignment and all required related entities.
        /// Returns (instructor, course, department) after saving to DB.
        /// </summary>
        private static (Instructor instructor, Course course, Department dept) SeedInstructorWithCourse(
            SchoolContext context,
            string lastName = "Smith",
            string firstName = "John",
            int courseId = 1001,
            string courseTitle = "Calculus",
            string deptName = "Mathematics")
        {
            var dept = CreateDepartment(deptName);
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = courseId,
                Title = courseTitle,
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var instructor = CreateInstructor(lastName, firstName);
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var ca = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            context.CourseAssignments.Add(ca);
            context.SaveChanges();

            return (instructor, course, dept);
        }

        // ===== Index Tests =====

        [Fact]
        public void Index_NoSelection_ReturnsAllInstructors()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Index_NoSelection_ReturnsAllInstructors));
            context.Instructors.Add(CreateInstructor("Adams", "Alice"));
            context.Instructors.Add(CreateInstructor("Brown", "Bob"));
            context.SaveChanges();

            using var controller = new InstructorsController(context);
            var result = controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            var instructors = model.Instructors.ToList();
            Assert.Equal(2, instructors.Count);
            Assert.Contains(instructors, i => i.LastName == "Adams");
            Assert.Contains(instructors, i => i.LastName == "Brown");
            Assert.Null(model.Courses);
        }

        [Fact]
        public void Index_WithInstructorSelected_PopulatesCourses()
        {
