            Assert.Equal("Wendy", model.FirstMidName);
            Assert.Equal(instructor.ID, model.ID);
        }

        // ===== Create GET Tests =====

        [Fact]
        public void Create_GET_ReturnsView()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_ReturnsView));
            using var controller = new InstructorsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
        }

        [Fact]
        public void Create_GET_SetsViewBagCourses()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_GET_SetsViewBagCourses));
            var dept = CreateDepartment("CS");
            context.Departments.Add(dept);
