            context.Courses.Add(new Course { CourseID = 3001, Title = "Intro CS", Credits = 3, DepartmentID = dept.DepartmentID });
            context.Courses.Add(new Course { CourseID = 3002, Title = "Data Structures", Credits = 4, DepartmentID = dept.DepartmentID });
            context.SaveChanges();

            using var controller = new InstructorsController(context);
            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var courses = controller.ViewBag.Courses as List<AssignedCourseData>;
            Assert.NotNull(courses);
            Assert.Equal(2, courses.Count);
            Assert.All(courses, c => Assert.False(c.Assigned));
            Assert.Contains(courses, c => c.CourseID == 3001 && c.Title == "Intro CS");
            Assert.Contains(courses, c => c.CourseID == 3002 && c.Title == "Data Structures");
