            var result = controller.Create(instructor, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidInstructor_SavesToDB()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_ValidInstructor_SavesToDB));
            var instructor = CreateInstructor("Johnson", "Jane");

            using var controller = new InstructorsController(context);
            controller.Create(instructor, null);

            var saved = context.Instructors.Single();
            Assert.Equal("Johnson", saved.LastName);
            Assert.Equal("Jane", saved.FirstMidName);
            Assert.Equal(new DateTime(2015, 8, 1), saved.HireDate);
        }

        [Fact]
        public void Create_POST_WithSelectedCourses_CreatesCourseAssignments()
        {
