            context.Departments.Add(dept);
            context.SaveChanges();
            context.Courses.Add(new Course { CourseID = 4001, Title = "Biology", Credits = 3, DepartmentID = dept.DepartmentID });
            context.Courses.Add(new Course { CourseID = 4002, Title = "Chemistry", Credits = 4, DepartmentID = dept.DepartmentID });
            context.SaveChanges();

            var instructor = CreateInstructor("Lee", "Linda");
            using var controller = new InstructorsController(context);
            var result = controller.Create(instructor, new[] { "4001", "4002" });

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var savedInstructor = context.Instructors
                .Include(i => i.CourseAssignments)
                .Single();
            Assert.Equal(2, savedInstructor.CourseAssignments.Count);
            var assignedCourseIds = savedInstructor.CourseAssignments.Select(ca => ca.CourseID).OrderBy(id => id).ToList();
            Assert.Equal(4001, assignedCourseIds[0]);
            Assert.Equal(4002, assignedCourseIds[1]);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
