            // Verify instructor was NOT saved to DB
            Assert.Empty(context.Instructors);
            // Verify ViewBag.Courses is populated for re-display
            var courses = controller.ViewBag.Courses as List<AssignedCourseData>;
            Assert.NotNull(courses);
