        }

        [Fact]
        public void Delete_GET_NotFound_ReturnsNotFound()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Delete_GET_NotFound_ReturnsNotFound));
            using var controller = new InstructorsController(context);

            var result = controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsInstructor()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Delete_GET_ValidId_ReturnsInstructor));
            var instructor = CreateInstructor("Clark", "Chris");
            context.Instructors.Add(instructor);
            context.SaveChanges();

            using var controller = new InstructorsController(context);
            var result = controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal("Clark", model.LastName);
            Assert.Equal("Chris", model.FirstMidName);
            Assert.Equal(instructor.ID, model.ID);
        }

        // ===== Delete POST Tests =====

        [Fact]
        public void DeleteConfirmed_RemovesInstructor()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(DeleteConfirmed_RemovesInstructor));
            var instructor = CreateInstructor("Davis", "Diana");
            context.Instructors.Add(instructor);
            context.SaveChanges();

            using var controller = new InstructorsController(context);
            controller.DeleteConfirmed(instructor.ID);

            Assert.Empty(context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_RedirectsToIndex()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(DeleteConfirmed_RedirectsToIndex));
            var instructor = CreateInstructor("Evans", "Eric");
            context.Instructors.Add(instructor);
            context.SaveChanges();

            using var controller = new InstructorsController(context);
            var result = controller.DeleteConfirmed(instructor.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(DeleteConfirmed_ClearsDepartmentAdministrator));
            var instructor = CreateInstructor("Foster", "Fiona");
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department
            {
                Name = "Physics",
                Budget = 80000m,
                StartDate = new DateTime(2023, 9, 1),
                InstructorID = instructor.ID
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            // Verify the department initially has the instructor assigned
            Assert.Equal(instructor.ID, dept.InstructorID);

            using var controller = new InstructorsController(context);
            controller.DeleteConfirmed(instructor.ID);

            var updatedDept = context.Departments.Single(d => d.DepartmentID == dept.DepartmentID);
            Assert.Null(updatedDept.InstructorID);
        }

        [Fact]
        public void DeleteConfirmed_SendsDeleteNotification()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(DeleteConfirmed_SendsDeleteNotification));
            var instructor = CreateInstructor("Grant", "Grace");
            context.Instructors.Add(instructor);
            context.SaveChanges();
            var instructorId = instructor.ID;

            using var controller = new InstructorsController(context);
            controller.DeleteConfirmed(instructorId);

            var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal(instructorId.ToString(), notification.EntityId);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Contains("deleted", notification.Message);
        }
    }
}

