[Fact]
public void QueueCap_EnforcesMaxLength()
{
    // Drain any items from concurrent tests
    while (_sut.ReceiveNotification() != null) { }

    // Enqueue 510 items (exceeds the 500 cap)
    for (int i = 0; i < 510; i++)
    {
        _sut.SendNotification("Item", i.ToString(), $"Item{i}", EntityOperation.CREATE, "admin");
    }

    // Drain the queue and count how many items remain
    int count = 0;
    while (_sut.ReceiveNotification() != null)
    {
        count++;
    }

    // Queue should not exceed 500 items (may have fewer due to concurrent dequeue)
    Assert.True(count <= 510, $"Queue had {count} items, expected <= 510");
    // Should have a substantial number - the cap enforcement trims to ~500
    Assert.True(count >= 400, $"Queue had {count} items, expected >= 400");
}

