public void Create_POST_ExactFileSizeLimit_Accepted()
{
    DrainNotificationQueue();
    using var context = CreateContext(nameof(Create_POST_ExactFileSizeLimit_Accepted));
    var dept = CreateTestDepartment(1, "Engineering");
    context.Departments.Add(dept);
    context.SaveChanges();

    // Use a real temp directory so file operations succeed
    var tempDir = Path.Combine(Path.GetTempPath(), "CoursesTest_" + Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(tempDir);
    try
    {
        var mockEnv = new Mock<IWebHostEnvironment>();
        mockEnv.Setup(e => e.WebRootPath).Returns(tempDir);
        mockEnv.Setup(e => e.ContentRootPath).Returns(tempDir);
        var mockLogger = new Mock<ILogger<CoursesController>>();
        using var controller = new CoursesController(context, mockEnv.Object, mockLogger.Object);

        var course = CreateTestCourse(9090, "Boundary Test", 1);

        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("valid.jpg");
        mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB — should be accepted
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = controller.Create(course, mockFile.Object);

        // Exactly 5MB should pass (> 5MB is the check, not >=)
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }
    finally
    {
        try { Directory.Delete(tempDir, true); } catch { }
    }
}

