        public void Index_WithCourseIdSelected_PopulatesEnrollments()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Index_WithCourseIdSelected_PopulatesEnrollments));

            var dept = CreateDepartment("Biology");
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 3001,
                Title = "Biology 101",
                Credits = 3,
                DepartmentID = dept.DepartmentID,
                Enrollments = new List<Enrollment>()
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var instructor = CreateInstructor("Taylor", "Tom");
            instructor.CourseAssignments = new List<CourseAssignment>();
            context.Instructors.Add(instructor);
            context.SaveChanges();

            context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });

            var student = new Student
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            context.Students.Add(student);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                CourseID = course.CourseID,
                StudentID = student.ID,
                Grade = Grade.A
            });
            context.SaveChanges();

            using var controller = new InstructorsController(context);
