        [Fact]
        public void Create_POST_WithSelectedCourses_AssignsCourses()
        {
            DrainNotificationQueue();
            using var context = CreateContext(nameof(Create_POST_WithSelectedCourses_AssignsCourses));

            var dept = CreateDepartment("Art");
            context.Departments.Add(dept);
            context.SaveChanges();

            var course1 = new Course { CourseID = 4001, Title = "Drawing", Credits = 2, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 4002, Title = "Painting", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            var instructor = CreateInstructor("West", "Wendy");
            using var controller = new InstructorsController(context);
            controller.Create(instructor, new[] { "4001", "4002" });

            var saved = context.Instructors
                .Include(i => i.CourseAssignments)
                .Single(i => i.LastName == "West");
            Assert.Equal(2, saved.CourseAssignments.Count);
            var courseIds = saved.CourseAssignments.Select(ca => ca.CourseID).OrderBy(x => x).ToList();
            Assert.Equal(4001, courseIds[0]);
            Assert.Equal(4002, courseIds[1]);
        }

