using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        private static SchoolContext CreateContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: $"DbInit_{dbName}")
                .Options;
            return new SchoolContext(options);
        }

        [Fact]
        public void Initialize_SeedsStudents()
        {
            using var context = CreateContext(nameof(Initialize_SeedsStudents));

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_SeedsInstructors()
        {
            using var context = CreateContext(nameof(Initialize_SeedsInstructors));

            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
        }

        [Fact]
        public void Initialize_SeedsDepartments()
        {
            using var context = CreateContext(nameof(Initialize_SeedsDepartments));

            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
            Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
            Assert.Contains(context.Departments, d => d.Name == "Mathematics" && d.Budget == 100000);
            Assert.Contains(context.Departments, d => d.Name == "Engineering");
            Assert.Contains(context.Departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_SeedsCourses()
        {
            using var context = CreateContext(nameof(Initialize_SeedsCourses));

            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.CourseID == 1050 && c.Title == "Chemistry");
            Assert.Contains(context.Courses, c => c.CourseID == 1045 && c.Title == "Calculus" && c.Credits == 4);
            Assert.Contains(context.Courses, c => c.CourseID == 2042 && c.Title == "Literature");
        }

        [Fact]
        public void Initialize_SeedsOfficeAssignments()
        {
            using var context = CreateContext(nameof(Initialize_SeedsOfficeAssignments));

            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Gowan 27");
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
        }

        [Fact]
        public void Initialize_SeedsCourseAssignments()
        {
            using var context = CreateContext(nameof(Initialize_SeedsCourseAssignments));

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollments()
        {
            using var context = CreateContext(nameof(Initialize_SeedsEnrollments));

            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
            // Verify specific enrollment with grade
            var alexanderChemistry = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .Single(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
            Assert.Equal(Grade.A, alexanderChemistry.Grade);

            // Verify enrollment without grade
            var anandChemistry = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .Single(e => e.Student.LastName == "Anand" && e.Course.Title == "Chemistry");
            Assert.Null(anandChemistry.Grade);
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicateData()
        {
            using var context = CreateContext(nameof(Initialize_CalledTwice_DoesNotDuplicateData));

            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context);

            // Should still have same counts - second call returns early
            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_DepartmentsHaveCorrectAdministrators()
        {
            using var context = CreateContext(nameof(Initialize_DepartmentsHaveCorrectAdministrators));

            DbInitializer.Initialize(context);

            var english = context.Departments.Include(d => d.Administrator)
                .Single(d => d.Name == "English");
            Assert.NotNull(english.Administrator);
            Assert.Equal("Abercrombie", english.Administrator.LastName);

            var math = context.Departments.Include(d => d.Administrator)
                .Single(d => d.Name == "Mathematics");
            Assert.Equal("Fakhouri", math.Administrator.LastName);
        }

        [Fact]
        public void Initialize_CoursesLinkedToCorrectDepartments()
        {
            using var context = CreateContext(nameof(Initialize_CoursesLinkedToCorrectDepartments));

            DbInitializer.Initialize(context);

            var chemistry = context.Courses.Include(c => c.Department)
                .Single(c => c.Title == "Chemistry");
            Assert.Equal("Engineering", chemistry.Department.Name);

            var calculus = context.Courses.Include(c => c.Department)
                .Single(c => c.Title == "Calculus");
            Assert.Equal("Mathematics", calculus.Department.Name);
        }
    }
}

