[Fact]
public void ReceiveNotification_DequeuesToCorrectOrder_FIFO()
{
    // Drain any stale notifications from parallel tests
    while (_sut.ReceiveNotification() != null) { }

    _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE, "admin");
    _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE, "admin");
    _sut.SendNotification("Department", "3", "Third", EntityOperation.DELETE, "admin");

    // Collect all notifications and find our 3 by entity ID
    var all = new System.Collections.Generic.List<Notification>();
    Notification n;
    while ((n = _sut.ReceiveNotification()) != null) all.Add(n);

    var first = all.FirstOrDefault(x => x.EntityId == "1" && x.EntityType == "Student");
    var second = all.FirstOrDefault(x => x.EntityId == "2" && x.EntityType == "Course");
    var third = all.FirstOrDefault(x => x.EntityId == "3" && x.EntityType == "Department");

    Assert.NotNull(first);
    Assert.NotNull(second);
    Assert.NotNull(third);

    Assert.Equal("CREATE", first.Operation);
    Assert.Equal("UPDATE", second.Operation);
    Assert.Equal("DELETE", third.Operation);

    // Verify FIFO ordering among our 3
    var firstIdx = all.IndexOf(first);
    var secondIdx = all.IndexOf(second);
    var thirdIdx = all.IndexOf(third);
    Assert.True(firstIdx < secondIdx, "First should come before second");
    Assert.True(secondIdx < thirdIdx, "Second should come before third");
}

